input.command:
python -c "
import json

path = r'C:\Users\x2\AppData\Local\Temp\deepseek_export\conversations.json'

with open(path, 'r', encoding='utf-8') as f:
    data = json.load(f)

# Extract messages from conversation [2] (English title 'Negotiate price increase with supplier')
conv = data[2]
mapping = conv['mapping']

def extract_messages(node_key, depth=0):
    node = mapping.get(node_key)
    if not node:
        return
    msg = node.get('message')
    if msg:
        fragments = msg.get('fragments', [])
        for frag in fragments:
            role = frag.get('role', 'user')
            text = ''
            hl = frag.get('highlight')
            if hl:
                for h in hl:
                    text += h.get('text', '')
            else:
                text = frag.get('content', '')
            if text:
                indent = '  ' * depth
                print(f'{indent}[{role}] {text[:200]}')
    children = node.get('children', [])
    for child in children:
        if child != node_key:
            extract_messages(child, depth+1)

extract_messages('root')
" 2>&1

