    $connected = $false
    for ($i = 0; $i -lt 15; $i++) {
        Start-Sleep -Seconds 2
        if (netstat -ano 2>&1 | Select-String "127.0.0.1:10808" -SimpleMatch) {
            $connected = $true
            break
        }
        Write-Log "Waiting Xray... ($($i+1)/15)"
    }
    if (-not $connected) {
        Write-Log "WARNING: Xray failed to start."
    } else {
        Write-Log "Xray OK (port 10808 open)."
    }
}

# 2) Start TUN service for system-wide routing (if installed)
$tunService = Get-Service -Name "AitekTun" -ErrorAction SilentlyContinue
if (-not $tunService -or $tunService.Status -ne 'Running') {
    $tunCheck = Get-NetAdapter -Name "aitek-tun" -ErrorAction SilentlyContinue
    if (-not $tunCheck) {
        Write-Log "TUN service not running. Attempt to start..."
        if ($tunService) {
            Start-Service -Name "AitekTun" -ErrorAction SilentlyContinue
            Start-Sleep -Seconds 3
        }
    } else {
        Write-Log "TUN interface 'aitek-tun' already active."
    }
} else {
    Write-Log "TUN service already running."
}

# 3) Set HTTPS_PROXY for this session (fallback for apps that respect env vars)
$env:HTTPS_PROXY = "socks5://127.0.0.1:10808"
$env:HTTP_PROXY = "socks5://127.0.0.1:10808"

# 4) Launch target app
if ($TargetApp) {
    Write-Log "Launching: $TargetApp"
    Start-Process -FilePath $TargetApp -Environment @{HTTPS_PROXY="socks5://127.0.0.1:10808"; HTTP_PROXY="socks5://127.0.0.1:10808"}
}

Write-Log "=== Done ==="

