display.text:
# Run this ONCE as Administrator to install the TUN proxy service
# This creates system-wide VPN (like Happ does via TUN)

$ServiceName = "AitekTun"
$Tun2Proxy = "D:\Happ\tun2\tun2proxy-bin.exe"
$LogFile = "$env:TEMP\aitek-tun-service.log"

# Check if already installed
$svc = Get-Service -Name $ServiceName -ErrorAction SilentlyContinue
if ($svc) {
    Write-Output "Service '$ServiceName' already exists (Status: $($svc.Status))."
    if ($svc.Status -eq 'Stopped') {
        Start-Service -Name $ServiceName
        Write-Output "Service started."
    }
    exit
}

# Create the service
$params = @{
    Name = $ServiceName
    BinaryPathName = "`"$Tun2Proxy`" --proxy socks5://127.0.0.1:10808 --setup --tun aitek-tun --dns over-tcp --daemonize --exit-on-fatal-error"
    DisplayName = "Aitek VPN TUN"
    Description = "System-wide VPN tunnel via Aitek subscription. Routes all traffic through SOCKS5 proxy."
    StartupType = "Automatic"
}
try {
    New-Service @params
    Start-Service -Name $ServiceName
    Write-Output "Service '$ServiceName' installed and started."
    Write-Output "TUN interface 'aitek-tun' created. All traffic goes through VPN."
} catch {
    Write-Output "FAILED: $_"
    Write-Output "Run this script as Administrator."
}

